(()=>{'use strict';let theme='dark';const url=new URL(location.href),incoming=url.searchParams.get('reader-theme');try{const saved=localStorage.getItem('taan-reader-theme');if(saved==='light'||saved==='dark')theme=saved;}catch(e){}if(incoming==='light'||incoming==='dark'){theme=incoming;try{localStorage.setItem('taan-reader-theme',theme);}catch(e){}url.searchParams.delete('reader-theme');try{history.replaceState(history.state,'',url.href);}catch(e){}}document.documentElement.dataset.readerTheme=theme;})();
